  @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if((code!=41&&code!=44)||result!=RESULT_OK||data==null||data.getData()==null)return;try(InputStream bounds=getContentResolver().openInputStream(data.getData());InputStream stream=getContentResolver().openInputStream(data.getData())){BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeStream(bounds,null,options);options.inJustDecodeBounds=false;options.inSampleSize=1;while(Math.max(options.outWidth,options.outHeight)/options.inSampleSize>1600)options.inSampleSize*=2;Bitmap bitmap=BitmapFactory.decodeStream(stream,null,options);if(bitmap==null)throw new IOException("Не удалось открыть изображение.");int max=Math.max(bitmap.getWidth(),bitmap.getHeight());Bitmap scaled=max>1280?Bitmap.createScaledBitmap(bitmap,Math.max(1,bitmap.getWidth()*1280/max),Math.max(1,bitmap.getHeight()*1280/max),true):bitmap;ByteArrayOutputStream out=new ByteArrayOutputStream();scaled.compress(Bitmap.CompressFormat.JPEG,78,out);if(out.size()>900000){out.reset();scaled.compress(Bitmap.CompressFormat.JPEG,55,out);}if(out.size()>900000)throw new IOException("Фото слишком большое. Выбери другой исходник.");byte[] bytes=out.toByteArray();if(code==44){uploadStudioSlide(bytes);return;}selectedSource=bytes;if(sourcePreview!=null){sourcePreview.setImageBitmap(scaled);sourcePreview.setVisibility(View.VISIBLE);}if(sourceCaption!=null)sourceCaption.setText("✓ Исходник приложен · "+Math.round(selectedSource.length/1024f)+" КБ");}catch(Exception e){message(e.getMessage());}}
  private void chooseSource(){Intent pick=new Intent(Intent.ACTION_GET_CONTENT);pick.setType("image/*");pick.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(Intent.createChooser(pick,"Выбери фото товара"),41);}catch(Exception e){message("Не удалось открыть фотографии.");}}
  private void chooseStudioSlide(int leadId){pendingStudioLead=leadId;Intent pick=new Intent(Intent.ACTION_GET_CONTENT);pick.setType("image/*");pick.addCategory(Intent.CATEGORY_OPENABLE);try{startActivityForResult(Intent.createChooser(pick,"Слайд для согласования"),44);}catch(Exception e){message("Не удалось открыть фотографии.");}}
  private void uploadSource(int id,String token,Done done){byte[] bytes=selectedSource;if(bytes==null){done.accept(new JSONObject(),null);return;}try{JSONObject body=new JSONObject();body.put("image_base64",Base64.encodeToString(bytes,Base64.NO_WRAP));pool.execute(()->{JSONObject data=new JSONObject();Exception error=null;HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(BASE+"/api/lead/"+id+"/source").openConnection();connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setConnectTimeout(15000);connection.setReadTimeout(20000);connection.setRequestProperty("Origin",BASE);connection.setRequestProperty("Content-Type","application/json; charset=utf-8");connection.setRequestProperty("X-AuraFX-Upload-Token",token);if(!session.isEmpty())connection.setRequestProperty("Cookie",session);try(OutputStream out=connection.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}InputStream response=connection.getResponseCode()<400?connection.getInputStream():connection.getErrorStream();if(response!=null){data=new JSONObject(new String(response.readAllBytes(),StandardCharsets.UTF_8));response.close();}if(connection.getResponseCode()>=400)throw new IOException(data.optString("error","Исходник не загрузился."));}catch(Exception e){error=e;}finally{if(connection!=null)connection.disconnect();}JSONObject result=data;Exception failure=error;main.post(()->done.accept(result,failure));});}catch(Exception e){done.accept(new JSONObject(),e);}}
  private void uploadStudioSlide(byte[] bytes){try{JSONObject body=new JSONObject();body.put("slide_no",pendingStudioSlide);body.put("caption",pendingStudioCaption);body.put("image_base64",Base64.encodeToString(bytes,Base64.NO_WRAP));int leadId=pendingStudioLead;request("POST","/api/admin/studio/projects/"+leadId+"/versions",body,(result,error)->{if(error!=null)message(error.getMessage());else{message("Слайд добавлен · клиент получит уведомление");adminStudio(leadId);}});}catch(Exception e){message(e.getMessage());}}
  private int statusColor(String status){switch(status){case "new":return CYAN;case "contacted":return 0xffc38aff;case "review":return 0xffffcf74;case "revision":return 0xffffa17e;case "done":return 0xff70e4ad;case "spam":return 0xffff839d;default:return MUTED;}}
  private TextView statusBadge(String status){TextView badge=text("● "+statusName(status),12,statusColor(status),true);badge.setPadding(dp(8),dp(5),dp(8),dp(5));GradientDrawable bg=shape(0xff332641,12);bg.setStroke(dp(1),statusColor(status));badge.setBackground(bg);return badge;}
  private void checkNotifications(){if(session.isEmpty())return;request("GET","/api/account/notifications",null,(data,error)->{if(error!=null)return;int unread=data.optInt("unread");if(bell!=null)bell.setText(unread>0?"🔔 "+Math.min(unread,99):"🔔");JSONArray list=data.optJSONArray("notifications");if(list==null||list.length()==0)return;JSONObject latest=list.optJSONObject(0);if(latest==null)return;int id=latest.optInt("id"),seen=getPreferences(0).getInt("last_event_id",0);if(id>seen){getPreferences(0).edit().putInt("last_event_id",id).apply();if(seen>0&&latest.isNull("read_at"))showSystemNotification(latest.optString("title"),latest.optString("body"),id);}});}
  private void scheduleNotificationJob(){try{JobScheduler scheduler=(JobScheduler)getSystemService(JOB_SCHEDULER_SERVICE);if(scheduler==null)return;JobInfo job=new JobInfo.Builder(71,new ComponentName(this,OrderNotificationJob.class)).setPeriodic(15*60*1000L).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).build();scheduler.schedule(job);}catch(SecurityException|IllegalArgumentException exception){android.util.Log.w("AuraFX","Background notifications unavailable",exception);}}
  private void showSystemNotification(String title,String body,int id){NotificationManager manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(manager==null)return;String channel="aurafx_orders";if(Build.VERSION.SDK_INT>=26)manager.createNotificationChannel(new NotificationChannel(channel,"Заказы AuraFX",NotificationManager.IMPORTANCE_DEFAULT));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)return;Intent open=new Intent(this,MainActivity.class);open.putExtra("open_notifications",true);PendingIntent action=PendingIntent.getActivity(this,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification note=new Notification.Builder(this,channel).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(body).setContentIntent(action).setAutoCancel(true).build();manager.notify(id,note);}
  private void notifications(){current=15;page.removeAllViews();title("AURAFX / УВЕДОМЛЕНИЯ","События заказа","Статусы заявок сохраняются здесь и доступны после входа в Telegram.");if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)add(page,button("Разрешить уведомления телефона",false,()->requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},42)),12);request("GET","/api/account/notifications",null,(d,e)->{if(current!=15)return;if(e!=null){add(page,button("Войти в профиль",true,()->render(5)),15);return;}JSONArray list=d.optJSONArray("notifications");if(list==null||list.length()==0){add(page,text("Пока уведомлений нет.",15,MUTED,false),18);return;}for(int i=0;i<list.length();i++){JSONObject event=list.optJSONObject(i);if(event==null)continue;LinearLayout c=card();add(c,text("✦  "+event.optString("title"),17,event.isNull("read_at")?CYAN:WHITE,true),0);add(c,text(event.optString("body"),14,MUTED,false),8);add(c,text(event.optString("created_at"),11,MUTED,false),8);add(page,c,10);}request("POST","/api/account/notifications/read",new JSONObject(),(x,err)->{if(err==null&&bell!=null)bell.setText("🔔");});});}
