  private void adminLeadQueue(String filter){adminShell("Очередь заказов · смена статуса сразу видна клиенту");LinearLayout filters=new LinearLayout(this);String[] modes={"В работе","Новые","Все"};String[] values={"active","new","all"};for(int i=0;i<3;i++){final String value=values[i];Button chip=button(modes[i],value.equals(filter),()->adminLeadQueue(value));chip.setTextSize(12);filters.addView(chip,new LinearLayout.LayoutParams(0,dp(51),1));}add(page,filters,14);LinearLayout list=column();add(page,list,17);int generation=adminGeneration;request("GET","/api/admin/leads",null,(d,e)->{if(current!=11||generation!=adminGeneration)return;if(e!=null){message(e.getMessage());return;}JSONArray a=d.optJSONArray("leads");if(a==null||a.length()==0){add(list,text("Заявок пока нет.",15,MUTED,false),0);return;}int shown=0;for(int i=0;i<a.length();i++){JSONObject lead=a.optJSONObject(i);if(lead==null)continue;String state=lead.optString("status");if("new".equals(filter)&&!"new".equals(state))continue;if("active".equals(filter)&&("done".equals(state)||"spam".equals(state)))continue;shown++;int id=lead.optInt("id");LinearLayout c=card();add(c,statusBadge(lead.optString("status","new")),0);add(c,text(lead.optString("product","Проект"),20,WHITE,true),7);add(c,text(lead.optString("marketplace")+" · "+lead.optInt("count")+" шт. · "+lead.optString("deadline"),13,MUTED,false),7);add(c,text("Контакт: "+lead.optString("contact","—"),14,WHITE,false),11);String note=lead.optString("comment");if(!note.isEmpty())add(c,text(note,14,MUTED,false),7);add(c,button("Открыть и изменить статус",false,()->adminLeadDetail(lead)),12);add(list,c,12);}if(shown==0)add(list,text("В этой очереди заявок пока нет.",15,MUTED,false),10);});}
  private void adminSource(int leadId,ImageView target){pool.execute(()->{HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(BASE+"/api/admin/leads/"+leadId+"/source").openConnection();c.setConnectTimeout(10000);c.setReadTimeout(12000);if(!session.isEmpty())c.setRequestProperty("Cookie",session);if(c.getResponseCode()!=200)return;try(InputStream in=c.getInputStream()){Bitmap bitmap=BitmapFactory.decodeStream(in);main.post(()->{if(active&&bitmap!=null)target.setImageBitmap(bitmap);});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}});}
