  private void adminStudio(int id){adminShell("Комната проекта #"+id+" · версии и правки");LinearLayout list=column();add(page,list,18);add(page,button("＋  Добавить версию слайда",true,()->{EditText slide=field("Номер слайда (1–30)",false);slide.setInputType(InputType.TYPE_CLASS_NUMBER);EditText caption=field("Что изменено в версии",true);LinearLayout fields=column();add(fields,slide,0);add(fields,caption,9);new android.app.AlertDialog.Builder(this).setTitle("Новая версия").setView(fields).setNegativeButton("Отмена",null).setPositiveButton("Выбрать изображение",(dialog,which)->{int number;try{number=Integer.parseInt(value(slide));}catch(Exception ignored){number=0;}if(number<1||number>30){message("Укажи номер слайда от 1 до 30.");return;}pendingStudioSlide=number;pendingStudioCaption=value(caption);chooseStudioSlide(id);}).show();}),11);int generation=adminGeneration;request("GET","/api/admin/studio/projects/"+id,null,(d,e)->{if(current!=11||generation!=adminGeneration)return;if(e!=null){add(list,text(e.getMessage(),15,MUTED,false),6);return;}JSONObject lead=d.optJSONObject("lead"),project=d.optJSONObject("project");if(lead!=null){add(list,text(lead.optString("product"),22,WHITE,true),0);add(list,statusBadge(lead.optString("status")),9);}if(project!=null&&!project.optString("brief").isEmpty()){add(list,text("БРИФ КЛИЕНТА",12,CYAN,true),20);add(list,text(project.optString("brief"),15,WHITE,false),9);}JSONArray versions=d.optJSONArray("versions"),comments=d.optJSONArray("comments");add(list,text("ВЕРСИИ СЛАЙДОВ",12,CYAN,true),22);if(versions==null||versions.length()==0)add(list,text("Загрузи первый слайд, чтобы клиент мог его посмотреть.",14,MUTED,false),8);else for(int i=0;i<versions.length();i++){JSONObject v=versions.optJSONObject(i);if(v==null)continue;int versionId=v.optInt("id");LinearLayout c=card();add(c,text("Слайд "+v.optInt("slide_no")+" · версия "+v.optInt("version_no"),17,WHITE,true),0);ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);c.addView(image,new LinearLayout.LayoutParams(-1,dp(230)));studioImage("/api/admin/studio/projects/"+id+"/versions/"+versionId+"/image",image);add(c,text(v.optString("caption"),14,MUTED,false),9);add(list,c,12);}add(list,text("ОБСУЖДЕНИЕ",12,CYAN,true),22);if(comments!=null)for(int i=0;i<comments.length();i++){JSONObject c=comments.optJSONObject(i);if(c==null)continue;LinearLayout bubble=card();add(bubble,text("client".equals(c.optString("author_role"))?"Клиент":"Вы / AuraFX",12,CYAN,true),0);add(bubble,text(c.optString("body"),15,WHITE,false),7);if(!c.isNull("x")&&!c.isNull("y"))add(bubble,text("Отметка на изображении: "+Math.round(c.optDouble("x")*100)+"% / "+Math.round(c.optDouble("y")*100)+"%",12,MUTED,false),7);add(list,bubble,9);}EditText reply=field("Ответ клиенту",true);add(list,reply,17);add(list,button("Отправить ответ",true,()->{if(value(reply).length()<2){message("Напиши ответ.");return;}try{JSONObject j=new JSONObject();j.put("body",value(reply));request("POST","/api/admin/studio/projects/"+id+"/comments",j,(x,err)->{if(err!=null)message(err.getMessage());else adminStudio(id);});}catch(Exception ex){message(ex.getMessage());}}),9);});}
