  private void request(String method,String path,JSONObject body,Done done){pool.execute(()->{JSONObject result=null;Exception error=null;HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(BASE+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(12000);c.setReadTimeout(12000);c.setRequestProperty("Accept","application/json");if(!session.isEmpty())c.setRequestProperty("Cookie",session);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json; charset=utf-8");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();String cookie=c.getHeaderField("Set-Cookie");if(cookie!=null&&cookie.startsWith("afx_user=")){session=cookie.split(";",2)[0];getPreferences(0).edit().putString("session",session).apply();}InputStream stream=code>=400?c.getErrorStream():c.getInputStream();String raw=stream==null?"{}":new String(stream.readAllBytes(),StandardCharsets.UTF_8);if(stream!=null)stream.close();result=new JSONObject(raw);if(code>=400)throw new IOException(result.optString("error","Сервер ответил: "+code));}catch(Exception ex){error=ex;}finally{if(c!=null)c.disconnect();}JSONObject d=result;Exception e=error;main.post(()->{if(active)done.accept(d==null?new JSONObject():d,e);});});}
